INSERT INTO institutions (
    institution_code,
    institution_name_kor,
    institution_name_eng,
    university_type,
    primary_region,
    source_as_of_date,
    source_url,
    sort_order,
    is_active,
    created_at,
    updated_at
)
SELECT
    CONCAT('UNI_', UPPER(LEFT(SHA2(university_name, 256), 16))),
    university_name,
    NULL,
    university_type,
    primary_region,
    source_as_of_date,
    source_url,
    sort_order,
    b'1',
    NOW(6),
    NOW(6)
FROM university_source
ON DUPLICATE KEY UPDATE
    university_type = VALUES(university_type),
    primary_region = VALUES(primary_region),
    source_as_of_date = VALUES(source_as_of_date),
    source_url = VALUES(source_url),
    updated_at = NOW(6);

CREATE TEMPORARY TABLE campus_source (
    university_name VARCHAR(100) NOT NULL,
    campus_name VARCHAR(100) NOT NULL,
    full_campus_name VARCHAR(150) NOT NULL,
    campus_relation VARCHAR(50) NOT NULL,
    campus_order INT NOT NULL,
    region VARCHAR(50) NOT NULL,
    source_as_of_date DATE NOT NULL,
    source_url VARCHAR(512) NOT NULL,
    PRIMARY KEY (university_name, campus_name),
    UNIQUE KEY uk_campus_source_order (university_name, campus_order),
    CONSTRAINT chk_campus_source_order_positive CHECK (campus_order > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

