INSERT INTO campuses (
    institution_id,
    campus_name,
    full_campus_name,
    campus_relation,
    campus_order,
    region,
    source_as_of_date,
    source_url,
    is_active,
    created_at,
    updated_at
)
SELECT
    i.institution_id,
    c.campus_name,
    c.full_campus_name,
    c.campus_relation,
    c.campus_order,
    c.region,
    c.source_as_of_date,
    c.source_url,
    b'1',
    NOW(6),
    NOW(6)
FROM campus_source c
JOIN institutions i
  ON i.institution_name_kor = c.university_name
ON DUPLICATE KEY UPDATE
    full_campus_name = VALUES(full_campus_name),
    campus_relation = VALUES(campus_relation),
    region = VALUES(region),
    source_as_of_date = VALUES(source_as_of_date),
    source_url = VALUES(source_url),
    is_active = b'1',
    updated_at = NOW(6);

DROP TEMPORARY TABLE campus_source;
DROP TEMPORARY TABLE university_source;

